if (element.querySelector('.custom-save-btn')) return;

var btn = document.createElement('button');
btn.className = 'custom-save-btn';
btn.type = 'button';
btn.textContent = 'Save';
btn.setAttribute('aria-label', 'Save pin');
btn.style.cssText = 'position:absolute;top:8px;right:8px;z-index:10;background:#e60023;color:#fff;border:none;border-radius:20px;padding:6px 14px;font-size:13px;font-weight:700;cursor:pointer;box-shadow:0 2px 8px rgba(0,0,0,0.25);line-height:1;opacity:0.95;transition:opacity 0.15s;';

btn.addEventListener('mouseenter', function() { btn.style.opacity = '1'; });
btn.addEventListener('mouseleave', function() { btn.style.opacity = '0.95'; });

var pinEl = element.closest('[data-test-id="pin"]');
if (pinEl) {
  var pinId = pinEl.getAttribute('data-test-pin-id') || '';
  btn.setAttribute('data-pin-id', pinId);
}

btn.addEventListener('click', function(e) {
  e.preventDefault();
  e.stopPropagation();

  var moreBtn = element.closest('[data-test-id="pin"]').querySelector('[data-test-id="more-actions-button"]');
  if (moreBtn) {
    moreBtn.click();
  }

  btn.style.background = '#45b6fe';
  btn.textContent = 'Saved';
  setTimeout(function() {
    btn.style.background = '#e60023';
    btn.textContent = 'Save';
  }, 1500);
});

element.style.position = 'relative';
element.appendChild(btn);
